UPDATE wo_workbook_sheet_line
   SET FILTER_RANGE = #{filterRange},
       MOD_DATETIME = CURRENT_TIMESTAMP,
       MOD_USER      = #{userKey}
 WHERE SHEET_SEQ = #{sheetSeq}
   AND DEL_DATETIME IS NULL

UPDATE wo_workbook_sheet_line
   SET TAB_COLOR    = #{tabColor},
       MOD_DATETIME = CURRENT_TIMESTAMP,
       MOD_USER      = #{userKey}
 WHERE SHEET_SEQ = #{sheetSeq}
   AND DEL_DATETIME IS NULL

UPDATE wo_workbook_sheet_line
   SET GRIDLINE_YN  = #{gridlineYn},
       MOD_DATETIME = CURRENT_TIMESTAMP,
       MOD_USER      = #{userKey}
 WHERE SHEET_SEQ = #{sheetSeq}
   AND DEL_DATETIME IS NULL

UPDATE wo_workbook_sheet_line
   SET SHEET_NAME   = #{sheetName},
       MOD_DATETIME = CURRENT_TIMESTAMP,
       MOD_USER      = #{userKey}
 WHERE SHEET_SEQ = #{sheetSeq}
   AND DEL_DATETIME IS NULL

UPDATE wo_workbook_sheet_line
   SET SHEET_NO     = #{sheetNo},
       MOD_DATETIME = CURRENT_TIMESTAMP,
       MOD_USER      = #{userKey}
 WHERE SHEET_SEQ = #{sheetSeq}
   AND DEL_DATETIME IS NULL

UPDATE wo_workbook_sheet_line
   SET DEL_DATETIME = CURRENT_TIMESTAMP,
       DEL_USER      = #{userKey}
 WHERE SHEET_SEQ = #{sheetSeq}
   AND DEL_DATETIME IS NULL

UPDATE wo_workbook_sheet_line
   SET DEL_DATETIME = NULL,
       DEL_USER      = NULL,
       MOD_DATETIME = CURRENT_TIMESTAMP,
       MOD_USER      = #{userKey}
 WHERE SHEET_SEQ = #{sheetSeq}
